<?php require '../includes/db.php';require '../includes/functions.php';admin_required();$x=$conn->query('SELECT COUNT(*) orders_count,COALESCE(SUM(total),0) revenue,COALESCE(AVG(total),0) average_order FROM orders')->fetch_assoc();$m=$conn->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) orders_count,SUM(total) revenue FROM orders GROUP BY month ORDER BY month DESC");$page_title='Sales Report';include '../includes/header.php';?><h1>Sales Summary</h1><div class="grid"><div class="panel"><p>Total Orders</p><h2><?=$x['orders_count']?></h2></div><div class="panel"><p>Total Revenue</p><h2><?=cash($x['revenue'])?></h2></div><div class="panel"><p>Average Order</p><h2><?=cash($x['average_order'])?></h2></div></div><h2>Monthly Summary</h2><table><tr><th>Month</th><th>Orders</th><th>Revenue</th></tr><?php while($r=$m->fetch_assoc()):?><tr><td><?=e($r['month'])?></td><td><?=$r['orders_count']?></td><td><?=cash($r['revenue'])?></td></tr><?php endwhile;?></table><?php include '../includes/footer.php';?>
